import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import CurriculumBuilder from '../components/CurriculumBuilder'; 

export default function InstructorPage() {
  const [courses, setCourses] = useState([]);
  const [view, setView] = useState('list');
  const [editCourse, setEditCourse] = useState(null);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({ 
    title: '', description: '', shortDescription: '', category: 'Programming', 
    level: 'beginner', price: 0, language: 'English', whatYouLearn: [''], requirements: [''], tags: '' 
  });

  const [modules, setModules] = useState([]);

  useEffect(() => {
    axios.get('/api/courses/instructor/my-courses')
      .then(r => setCourses(r.data || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const handleSave = async () => {
    try {
      const cleanedModules = (modules || []).map(m => ({
        ...m,
        content: (m.content || []).map(item => {
          const { isUploading, ...rest } = item; 
          return rest;
        })
      }));

      const payload = { 
        ...form, 
        modules: cleanedModules, 
        tags: typeof form.tags === 'string' ? form.tags.split(',').map(t => t.trim()).filter(Boolean) : form.tags, 
        whatYouLearn: (form.whatYouLearn || []).filter(Boolean), 
        requirements: (form.requirements || []).filter(Boolean) 
      };

      if (editCourse) {
        const { data } = await axios.put(`/api/courses/${editCourse._id}`, payload);
        setCourses(cs => cs.map(c => c._id === data._id ? data : c));
        toast.success('Updated!');
      } else {
        const { data } = await axios.post('/api/courses', payload);
        setCourses(cs => [data, ...cs]);
        toast.success('Created!');
      }
      setView('list'); setEditCourse(null);
    } catch (err) { toast.error(err.response?.data?.message || 'Save failed'); }
  };

  const startEdit = (c) => {
    setEditCourse(c);
    setForm({ 
        ...c, 
        tags: Array.isArray(c.tags) ? c.tags.join(', ') : '', 
        whatYouLearn: c.whatYouLearn?.length ? c.whatYouLearn : [''], 
        requirements: c.requirements?.length ? c.requirements : [''] 
    });
    setModules(c.modules || []); 
    setView('create');
  };

  return (
    <div style={{ minHeight: '100vh', paddingTop: 90 }}>
      <div className="page-container" style={{ padding: '40px 24px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 36 }}>
          <h1 style={{ fontSize: 32, fontWeight: 900 }}>Instructor Studio</h1>
          {view === 'list' ? (
            <button className="btn btn-primary" onClick={() => { setEditCourse(null); setModules([]); setView('create'); }}>+ New Course</button>
          ) : (
            <button className="btn btn-ghost" onClick={() => setView('list')}>← Back</button>
          )}
        </div>

        {view === 'list' ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {loading ? <div className="loader" /> : courses.map(c => (
              <div key={c._id} className="glass" style={{ padding: 20, borderRadius: 16, display: 'flex', justifyContent: 'space-between' }}>
                <div>
                    <h3 style={{ fontWeight: 700 }}>{c.title}</h3>
                    <p style={{ fontSize: 12, color: '#6b6490' }}>{c.category} • {c.modules?.length || 0} modules</p>
                </div>
                <button className="btn btn-sm btn-ghost" onClick={() => startEdit(c)}>✏️ Edit</button>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ maxWidth: 800 }}>
            <div className="form-group" style={{ marginBottom: 20 }}>
              <label className="form-label">Title</label>
              <input className="input" value={form.title} onChange={e => setForm({...form, title: e.target.value})} />
            </div>
            <CurriculumBuilder modules={modules} setModules={setModules} />
            <button className="btn btn-primary btn-lg" style={{ marginTop: 20 }} onClick={handleSave}>Save Course</button>
          </div>
        )}
      </div>
    </div>
  );
}
